body.content:
.product-desktop-ux {
  display: none;
}

.sticky-desktop-atc {
  display: none;
}

.product-form__matching-set-hint {
  flex: 1 1 100%;
  margin: 0.15rem 0 0;
  padding: 0.85rem 1rem;
  border: 0.1rem solid rgba(92, 127, 84, 0.16);
  border-radius: 1rem;
  background: rgba(244, 248, 241, 0.84);
  color: rgba(17, 24, 39, 0.72);
  font-size: 1.18rem;
  line-height: 1.45;
}

.matching-size-guide__snapshot {
  margin-top: 1rem;
}

.matching-size-guide__snapshot-card {
  border: 0.1rem solid rgba(17, 24, 39, 0.08);
  border-radius: 1.8rem;
  background:
    radial-gradient(circle at top right, rgba(245, 213, 182, 0.28), transparent 42%),
    linear-gradient(180deg, #fffdf9 0%, #fff8f0 100%);
  box-shadow: 0 1.4rem 3rem rgba(17, 24, 39, 0.06);
  overflow: hidden;
  padding: 1.25rem;
}

.matching-size-guide {
  margin-top: 0.8rem;
  border: 0.1rem solid rgba(17, 24, 39, 0.08);
  border-radius: 1.6rem;
  background: #ffffff;
  overflow: hidden;
}

.matching-size-guide summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  list-style: none;
  cursor: pointer;
  padding: 1.15rem 1.25rem;
  font-size: 1.2rem;
  font-weight: 700;
  color: #101418;
}

.matching-size-guide summary::-webkit-details-marker {
  display: none;
}

.matching-size-guide summary::after {
  content: '';
  flex: 0 0 auto;
  width: 0.9rem;
  height: 0.9rem;
  margin-right: 0.2rem;
  border-right: 0.2rem solid rgba(17, 24, 39, 0.62);
  border-bottom: 0.2rem solid rgba(17, 24, 39, 0.62);
  transform: rotate(45deg) translateY(-0.1rem);
  transform-origin: 50% 50%;
  transition: transform 0.2s ease, border-color 0.2s ease;
}

.matching-size-guide[open] summary::after {
  transform: rotate(-135deg) translateY(-0.05rem);
}

.matching-size-guide summary:hover::after {
  border-color: #101418;
}

.matching-size-guide__content {
  padding: 0 1.25rem 1.25rem;
}

.matching-size-guide__toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.15rem 0 1rem;
}

.matching-size-guide__intro {
  min-width: 0;
}

.matching-size-guide__eyebrow {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(17, 24, 39, 0.5);
}

.matching-size-guide__selected {
  margin: 0.35rem 0 0;
  font-size: 1.18rem;
  line-height: 1.5;
  color: rgba(17, 24, 39, 0.76);
}

.matching-size-guide__selected strong {
  color: #101418;
}

.matching-size-guide__metrics {
  display: grid;
  gap: 0.8rem;
  grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
}

/* CRO Tier 1 (May 2026): the measurement grid is collapsed by default
   so it doesn't dominate the viewport before the shopper commits. The
   toggle button below the size summary reveals it on demand. */
.matching-size-guide__metrics--collapsible[hidden] {
  display: none !important;
}

.matching-size-guide__metrics--collapsible {
  margin-top: 0.8rem;
}

.matching-size-guide__metrics-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0.4rem 0 0;
  padding: 0.55rem 0;
  border: 0;
  background: transparent;
  font-size: 1.05rem;
  font-weight: 600;
  line-height: 1.3;
  color: #1D8656;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 0.25rem;
  text-decoration-thickness: 0.1rem;
}

.matching-size-guide__metrics-toggle:hover,
.matching-size-guide__metrics-toggle:focus-visible {
  color: #156a44;
  outline: none;
}

.matching-size-guide__metrics-toggle-icon {
  display: inline-block;
  width: 0.7rem;
  height: 0.7rem;
  border-right: 0.18rem solid currentColor;
  border-bottom: 0.18rem solid currentColor;
  transform: rotate(45deg) translateY(-0.05rem);
  transition: transform 0.18s ease;
}

.matching-size-guide__metrics-toggle[aria-expanded='true'] .matching-size-guide__metrics-toggle-icon {
  transform: rotate(-135deg) translateY(-0.05rem);
}

.matching-size-guide__metric {
  min-width: 0;
  padding: 1rem;
  border: 0.1rem solid rgba(17, 24, 39, 0.08);
  border-radius: 1.4rem;
  background: rgba(255, 255, 255, 0.82);
}

.matching-size-guide__metric-label {
  display: block;
  margin-bottom: 0.45rem;
  font-size: 0.98rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(17, 24, 39, 0.52);
}

.matching-size-guide__metric-value {
  display: block;
  font-size: 1.32rem;
  line-height: 1.35;
  color: #101418;
}

.matching-size-guide__unit-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.35rem;
  border: 0.1rem solid rgba(17, 24, 39, 0.08);
  border-radius: 999px;
  background: rgba(248, 244, 239, 0.85);
}

.matching-size-guide__unit-button {
  min-width: 4.2rem;
  min-height: 3.2rem;
  padding: 0 1rem;
  border: 0;
  border-radius: 999px;
  background: transparent;
  font-size: 1.1rem;
  font-weight: 700;
  color: rgba(17, 24, 39, 0.68);
  cursor: pointer;
  transition: background-color 0.2s ease, color 0.2s ease, box-shadow 0.2s ease;
}

.matching-size-guide__unit-button:hover {
  color: #101418;
}

.matching-size-guide__unit-button.is-active {
  background: #ffffff;
  color: #101418;
  box-shadow: 0 0.6rem 1.2rem rgba(17, 24, 39, 0.08);
}

.matching-size-guide__grid {
  display: grid;
  gap: 1rem;
}

.matching-size-guide__card {
  border: 0.1rem solid rgba(17, 24, 39, 0.08);
  border-radius: 1.4rem;
  background: #fbfbfd;
  overflow: hidden;
}

.matching-size-guide__card h3 {
  margin: 0;
  padding: 1rem 1.1rem 0.4rem;
  font-size: 1.35rem;
}

.matching-size-guide__helper {
  margin: 0 1.1rem 0.9rem;
  font-size: 1.1rem;
  line-height: 1.45;
  color: rgba(17, 24, 39, 0.68);
}

.matching-size-guide__helper--snapshot {
  margin: 0.5rem 0 0;
}

.matching-size-guide__table-wrap {
  overflow-x: auto;
}

.matching-size-guide__table {
  width: 100%;
  border-collapse: collapse;
  font-size: 1.15rem;
}

.matching-size-guide__table th,
.matching-size-guide__table td {
  padding: 0.85rem 1.05rem;
  border-bottom: 0.1rem solid rgba(17, 24, 39, 0.06);
  text-align: left;
  white-space: nowrap;
}

.matching-size-guide__table th {
  font-weight: 700;
  color: rgba(17, 24, 39, 0.74);
  background: rgba(17, 24, 39, 0.03);
}

.matching-size-guide__table th:first-child,
.matching-size-guide__table td:first-child {
  position: sticky;
  left: 0;
  text-align: left;
  background-clip: padding-box;
}

.matching-size-guide__table th:first-child {
  z-index: 2;
  background: #f7efe8;
  box-shadow: 0.1rem 0 0 rgba(17, 24, 39, 0.08);
}

.matching-size-guide__table td:first-child {
  z-index: 1;
  background: #ffffff;
  box-shadow: 0.1rem 0 0 rgba(17, 24, 39, 0.08);
  color: #101418;
  font-weight: 600;
}

.matching-size-guide__table tbody tr.is-selected td {
  background: rgba(226, 197, 168, 0.18);
}

.matching-size-guide__table tbody tr.is-selected td:first-child {
  background: #eadbce;
  font-weight: 700;
  color: #8a5c3e;
}

.matching-size-guide__table tr:last-child td {
  border-bottom: 0;
}

body.dlm-fit-modal-open {
  overflow: hidden;
}

.dlm-fit-modal[hidden] {
  display: none !important;
}

.dlm-fit-modal {
  position: fixed;
  inset: 0;
  z-index: 1200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2.4rem;
}

.dlm-fit-modal__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(15, 23, 42, 0.42);
}

.dlm-fit-modal__dialog {
  position: relative;
  z-index: 1;
  width: min(92rem, 100%);
  max-height: min(76rem, calc(100vh - 4.8rem));
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-radius: 0.8rem;
  background: #ffffff;
  box-shadow: 0 2rem 5rem rgba(15, 23, 42, 0.22);
  outline: none;
}

.dlm-fit-modal__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1.6rem;
  padding: 1.6rem 1.8rem 1.2rem;
  border-bottom: 0.1rem solid rgba(17, 24, 39, 0.08);
}

.dlm-fit-modal__eyebrow {
  margin: 0 0 0.35rem;
  color: rgba(17, 24, 39, 0.54);
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.dlm-fit-modal__title {
  margin: 0;
  color: #101418;
  font-size: 1.8rem;
  line-height: 1.2;
}

.dlm-fit-modal__close {
  width: 3.6rem;
  height: 3.6rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: rgba(17, 24, 39, 0.07);
  color: #101418;
  font-size: 2.2rem;
  line-height: 1;
  cursor: pointer;
}

.dlm-fit-modal__close:hover,
.dlm-fit-modal__close:focus-visible {
  background: rgba(17, 24, 39, 0.12);
  outline: none;
}

.dlm-fit-modal__tabs {
  display: flex;
  gap: 0.6rem;
  padding: 1.2rem 1.8rem 0;
  overflow-x: auto;
}

.dlm-fit-modal__tab {
  min-height: 3.4rem;
  padding: 0 1.3rem;
  border: 0.1rem solid rgba(17, 24, 39, 0.12);
  border-radius: 999px;
  background: #ffffff;
  color: rgba(17, 24, 39, 0.72);
  font-size: 1.12rem;
  font-weight: 700;
  white-space: nowrap;
  cursor: pointer;
}

.dlm-fit-modal__tab:hover,
.dlm-fit-modal__tab:focus-visible {
  border-color: rgba(29, 134, 86, 0.55);
  color: #146642;
  outline: none;
}

.dlm-fit-modal__tab.is-active {
  border-color: #1D8656;
  background: #1D8656;
  color: #ffffff;
}

.dlm-fit-modal__body {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: 1.2rem 1.8rem 1.8rem;
}

.dlm-fit-modal__body .matching-size-guide__toolbar {
  padding-top: 0;
}

.dlm-fit-modal__body .matching-size-guide__card {
  border-radius: 0.8rem;
}

.dlm-fit-modal__body .matching-size-guide__table tbody tr {
  outline: none;
}

.dlm-fit-modal__body .matching-size-guide__table tbody tr:hover td,
.dlm-fit-modal__body .matching-size-guide__table tbody tr:focus-within td,
.dlm-fit-modal__body .matching-size-guide__table tbody tr:focus td {
  background: rgba(29, 134, 86, 0.1);
}

.dlm-fit-modal__body .matching-size-guide__table tbody tr:hover td:first-child,
.dlm-fit-modal__body .matching-size-guide__table tbody tr:focus-within td:first-child,
.dlm-fit-modal__body .matching-size-guide__table tbody tr:focus td:first-child {
  background: #dff3e9;
  color: #0f5235;
}

.dlm-fit-modal__body .matching-size-guide__table tbody tr:focus-visible {
  outline: 0.2rem solid rgba(29, 134, 86, 0.55);
  outline-offset: -0.2rem;
}

@media screen and (min-width: 990px) {
  .dlm-fit-modal {
    padding: 1.6rem;
  }

  .dlm-fit-modal__dialog {
    width: min(150rem, calc(100vw - 3.2rem));
    max-height: min(82rem, calc(100vh - 3.2rem));
  }

  .dlm-fit-modal__body .matching-size-guide__table-wrap {
    overflow-x: visible;
  }

  .dlm-fit-modal__body .matching-size-guide__table {
    table-layout: auto;
  }

  .dlm-fit-modal__body .matching-size-guide__table th,
  .dlm-fit-modal__body .matching-size-guide__table td {
    padding: 0.72rem 0.7rem;
    white-space: normal;
  }

  .dlm-fit-modal__body .matching-size-guide__table th:first-child,
  .dlm-fit-modal__body .matching-size-guide__table td:first-child {
    white-space: nowrap;
  }
}

@media screen and (max-width: 749px) {
  .dlm-fit-modal {
    align-items: flex-end;
    padding: 1rem;
  }

  .dlm-fit-modal__dialog {
    max-height: calc(100vh - 2rem);
  }

  .dlm-fit-modal__header,
  .dlm-fit-modal__tabs,
  .dlm-fit-modal__body {
    padding-left: 1.2rem;
    padding-right: 1.2rem;
  }
}

@media screen and (min-width: 990px) {
  .product-desktop-ux {
    display: block;
    margin-top: 1.4rem;
  }

  .product-desktop-ux__highlights {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 1rem;
  }

  .product-desktop-ux__highlight {
    display: flex;
    flex-direction: column;
    gap: 0.45rem;
    min-height: 12rem;
    padding: 1.35rem 1.45rem;
    border: 0.1rem solid rgba(17, 24, 39, 0.08);
    border-radius: 1.6rem;
    background: linear-gradient(180deg, rgba(250, 251, 255, 0.96), rgba(245, 247, 251, 0.96));
    color: rgb(var(--color-foreground));
    text-decoration: none;
  }

  .product-desktop-ux__highlight--link:hover {
    border-color: rgba(17, 24, 39, 0.18);
    box-shadow: 0 1.2rem 2.4rem rgba(17, 24, 39, 0.08);
  }

  .product-desktop-ux__label,
  .product-photo-strip__eyebrow,
  .product-matching-set__eyebrow {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: rgba(17, 24, 39, 0.56);
  }

  .product-desktop-ux__value {
    font-size: 1.55rem;
    line-height: 1.3;
    color: #101418;
  }

  .product-desktop-ux__copy {
    font-size: 1.22rem;
    line-height: 1.55;
    color: rgba(17, 24, 39, 0.72);
  }

  .matching-size-guide__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .matching-size-guide__selected {
    font-size: 1.25rem;
  }

  .matching-size-guide__metric-value {
    font-size: 1.4rem;
  }

  .product-matching-set {
    margin-top: 1rem;
    padding: 1.6rem;
    border-radius: 1.8rem;
    background: linear-gradient(180deg, #f4faf6 0%, #ecf7f1 100%);
    border: 0.15rem solid rgba(29, 134, 86, 0.32);
    box-shadow: 0 2px 14px rgba(29, 134, 86, 0.08);
  }
  /* CRO Step 5: Brand the matching-set eyebrow so the block reads as
     the primary buying action on family-set products. */
  .product-matching-set__eyebrow {
    margin: 0 0 0.3rem;
    font-size: 1.1rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #1D8656;
    font-weight: 700;
  }

  .product-matching-set__title,
  .product-photo-strip__title {
    margin: 0.2rem 0 0;
    font-size: 1.8rem;
    line-height: 1.25;
    color: #101418;
  }

  .product-matching-set__copy {
    margin: 0.7rem 0 0;
    font-size: 1.28rem;
    line-height: 1.55;
    color: rgba(17, 24, 39, 0.72);
  }

  .product-matching-set__grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 1rem;
    margin-top: 1.35rem;
  }

  .product-matching-set__card {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    padding: 1.2rem;
    border-radius: 1.4rem;
    background: rgba(255, 255, 255, 0.88);
    border: 0.1rem solid rgba(17, 24, 39, 0.08);
  }

  .product-matching-set__card-header {
    display: flex;
    justify-content: space-between;
    gap: 0.8rem;
    align-items: baseline;
  }

  .product-matching-set__card-title {
    font-size: 1.35rem;
    font-weight: 700;
    color: #101418;
  }

  .product-matching-set__card-helper {
    font-size: 1.15rem;
    color: rgba(17, 24, 39, 0.7);
  }

  .product-matching-set__select {
    min-height: 4.8rem;
    padding: 0 1.4rem;
    border-radius: 999px;
    border: 0.1rem solid rgba(17, 24, 39, 0.14);
    background: #ffffff;
    font-size: 1.35rem;
  }

  .product-matching-set__footer {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    gap: 1rem;
    margin-top: 1.4rem;
  }

  .product-matching-set__selection {
    flex: 1;
    min-width: 0;
  }

  .product-matching-set__empty,
  .product-matching-set__status {
    margin: 0;
    font-size: 1.2rem;
    line-height: 1.5;
    color: rgba(17, 24, 39, 0.72);
  }

  .product-matching-set__chips {
    display: flex;
    flex-wrap: wrap;
    gap: 0.55rem;
  }

  .product-matching-set__chip {
    display: inline-flex;
    align-items: center;
    padding: 0.55rem 0.8rem;
    border-radius: 999px;
    background: rgba(17, 24, 39, 0.06);
    font-size: 1.12rem;
    font-weight: 600;
    color: #101418;
  }

  .product-matching-set__total {
    display: block;
    margin-top: 0.7rem;
    font-size: 1.35rem;
    color: #101418;
  }

  /* CRO Tier 1 (May 2026): the matching-set CTA used to be styled as
     the primary action (filled green) which competed with the main
     "Add to cart" and split shopper intent. Demote it to a secondary
     outline-style button so the single-product Add-to-Cart above
     remains the dominant primary action. Pre-purchase intent stays
     consolidated on one CTA; the bundle becomes a clear *upsell*. */
  .product-matching-set__button {
    min-width: 22rem;
    min-height: 4.8rem;
    padding: 0 2.4rem;
    border: 0.15rem solid #1D8656;
    border-radius: 999px;
    background: #ffffff;
    color: #1D8656;
    font-weight: 700;
    font-size: 1.35rem;
    letter-spacing: 0.01em;
    box-shadow: none;
    transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, transform 0.05s ease;
  }

  .product-matching-set__button:hover:not([disabled]) {
    background: #f4faf6;
    color: #146642;
    border-color: #146642;
  }

  .product-matching-set__button:active:not([disabled]) {
    transform: translateY(1px);
  }

  .product-matching-set__button::before,
  .product-matching-set__button::after {
    content: none;
  }

  .product-matching-set__button[disabled] {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* CRO Tier 1 (May 2026): the previous CRO Step 5 block here inverted
     the hierarchy — making the matching-set CTA primary and demoting
     the main Add-to-Cart to outline. External CRO audit flagged this
     as conversion poison (two competing primaries above the fold +
     "Or add just one piece:" preamble that weakens momentum). The
     primary Add-to-Cart now keeps its default Dawn primary style and
     the matching-set CTA is the visually secondary upsell. */

  .product-photo-strip {
    margin-top: 1rem;
    padding: 1.5rem;
    border-radius: 1.8rem;
    border: 0.1rem solid rgba(17, 24, 39, 0.08);
    background: #ffffff;
  }

  .product-photo-strip__header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    gap: 1rem;
  }

  .product-photo-strip__link {
    font-size: 1.22rem;
    font-weight: 600;
    color: #101418;
    text-decoration: underline;
  }

  .product-photo-strip__media {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.8rem;
    margin-top: 1.2rem;
  }

  .product-photo-strip__media a {
    display: block;
    border-radius: 1.2rem;
    overflow: hidden;
    background: rgba(17, 24, 39, 0.04);
    aspect-ratio: 1 / 1;
  }

  .product-photo-strip__media img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .sticky-desktop-atc {
    position: fixed;
    right: 2rem;
    bottom: 2rem;
    z-index: 40;
    display: flex;
    align-items: center;
    gap: 1.1rem;
    width: min(38rem, calc(100vw - 4rem));
    padding: 1.2rem;
    border-radius: 1.8rem;
    background: rgba(255, 255, 255, 0.96);
    border: 0.1rem solid rgba(17, 24, 39, 0.12);
    box-shadow: 0 1.6rem 4rem rgba(17, 24, 39, 0.16);
    opacity: 0;
    pointer-events: none;
    transform: translateY(1.4rem);
    transition: opacity 0.24s ease, transform 0.24s ease;
  }

  .sticky-desktop-atc.is-visible {
    opacity: 1;
    pointer-events: auto;
    transform: translateY(0);
  }

  .sticky-desktop-atc__meta {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    min-width: 0;
  }

  .sticky-desktop-atc__price {
    font-size: 1.65rem;
    font-weight: 700;
    color: #101418;
  }

  .sticky-desktop-atc__size {
    font-size: 1.1rem;
    color: rgba(17, 24, 39, 0.68);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .sticky-desktop-atc__button {
    flex: 1;
