@media screen and (min-width: 990px) and (max-width: 1220px) {
  .product-desktop-ux__highlights,
  .matching-size-guide__grid,
  .product-matching-set__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .product-desktop-ux__highlight:last-child {
    grid-column: 1 / -1;
  }
}

@media screen and (min-width: 990px) and (max-width: 1099px) {
  .product-matching-set__footer {
    flex-direction: column;
    align-items: stretch;
  }

