    width: 100%;
    min-width: 0;
  }
}

/* ─────────────────────────────────────────────────────────────────────
   CRO redesign May 2026 — PDP "Build Your Matching Set" flow
   ─────────────────────────────────────────────────────────────────────

   Scope: anything inside .product__info-container--matching-set, i.e.
   only products tagged / collected as matching-set / mommy-and-me /
   daddy-and-me / family-matching. Non-matching-set products keep their
   Dawn-default presentation.

   Goals (from CRO spec):
   ─ Single primary CTA      (hide the standalone Add-to-Cart submit)
   ─ Family-member cards     (pills + qty stepper + remove)
   ─ Progressive disclosure  (+ Add Dad / + Add Baby chips)
   ─ Live summary            (count, total, savings) above the CTA
   ─ Compact trust row       (under the CTA, not below the fold)
   ─ Collapse measurement /
     Purchase Confidence     (so first viewport is cards + CTA)
   ─ Compress vertical
     spacing ~40–60%
   ────────────────────────────────────────────────────────────────── */

/* Make sure the matching-set block paints — historically it ships
   hidden until JS unhides; on matching-set products we want it
   prominently visible. */
.product__info-container--matching-set .product-desktop-ux {
  display: block;
}

.product__info-container--matching-set .product-matching-set__role-price,
.product__info-container--matching-set .product-matching-set__card-price,
.product__info-container--matching-set .product-matching-set__card-price--header {
  display: none !important;
}

/* 1. Single primary CTA + single source of size truth.
   On matching-set products the standalone Add-to-Cart submit + its
   dynamic checkout button are hidden so the matching-set CTA below
   reads as the only primary path. Customers buying a single piece
   simply leave one card visible. The main variant-selects is also
   hidden — sizing happens per-family-member-card, not via the
   standalone size picker, so showing both creates two competing
   size selectors. Hiding only the picker UI; the underlying
   variant-selects element still receives change events from the
   bundle so anything downstream of it (e.g. price/url sync) keeps
   working. */
.product__info-container--matching-set .product-form__submit,
.product__info-container--matching-set .product-form__buttons {
  display: none !important;
}
.product__info-container--matching-set .product-form__dynamic-checkout {
  display: none !important;
}
/* On bundle products hide the legacy variant pickers that are now
   handled per-family-member-card inside the bundle:
   • SIZE — discriminator: aria-describedby="size-conversion-message"
     emitted only on size fieldset / size <select> by the Liquid template.
   • COLOR — discriminator: .product-form__input--swatch or
     .product-form__input--color-image (color picker variants in Dawn).
   Per-card axis pickers cover both. Type (Shirt/Dress) stays visible
   above the bundle because it's a role-discriminator that re-seeds
   the default-visible family members (handled by JS reactivity). */
.product__info-container--matching-set variant-selects > fieldset[aria-describedby="size-conversion-message"],
.product__info-container--matching-set variant-selects > .product-form__input:has([aria-describedby="size-conversion-message"]),
.product__info-container--matching-set variant-selects > fieldset.product-form__input--swatch,
.product__info-container--matching-set variant-selects > fieldset.product-form__input--color-image,
.product__info-container--matching-set variant-selects > .product-form__input--swatch,
.product__info-container--matching-set variant-selects > .product-form__input--color-image {
  display: none !important;
}

/* When Type perfectly partitions roles (data-type-implicit attribute
   set by initMatchingSetBuilder via detectImplicitTypeMapping), the
   global Type picker is redundant — each role's natural Type is
   implied. Hide every remaining option group; the JS will still keep
   it in the DOM so any underlying form data stays consistent. The
   ::variant-selects element itself still emits change events which
   the bundle ignores in implicit mode. */
.product__info-container--matching-set[data-type-implicit="true"] variant-selects > .product-form__input,
.product__info-container--matching-set[data-type-implicit="true"] variant-selects > fieldset.product-form__input,
.product__info-container--matching-set[data-type-implicit="true"] variant-selects > .product-form__step-heading {
  display: none !important;
}
/* Hide the step-mini-headings too (they were "1. CHOOSE SIZE / 2. PICK
   COLOR" numbering that no longer makes sense once size is removed). */
.product__info-container--matching-set variant-selects > .product-form__step-heading {
  display: none !important;
}
/* Hide the legacy size-guide subtree (snapshot, conversion message,
   chart wrapper). The matching-size-guide details element stays in
   the DOM with [hidden] so the per-card "Find {role}'s fit" link can
   still un-hide it via the shared trigger handler. */
.product__info-container--matching-set variant-selects > #size-conversion-message,
.product__info-container--matching-set variant-selects > .matching-size-guide__snapshot,
.product__info-container--matching-set variant-selects > .size-chart-wrapper {
  display: none !important;
}

/* Style the surviving Color / Type / Style pickers above the bundle
   card so they read as the global "shared across family" pickers and
   don't feel like leftover Dawn chrome. */
.product__info-container--matching-set variant-selects > .product-form__input {
  margin: 0.4rem 0 0.9rem !important;
}
.product__info-container--matching-set variant-selects > .product-form__input legend.form__label,
.product__info-container--matching-set variant-selects > .product-form__input > label.form__label {
  font-size: 1.15rem;
  font-weight: 700;
  color: #101418;
  margin-bottom: 0.45rem;
}

/* HUGE WHITE GAP root cause: sections/main-product.liquid reserves
   24.3rem (~243px) min-height on .matching-size-guide__snapshot--reserved
   to prevent layout shift when the size-guide snapshot loads. On
   bundle products that snapshot is hidden, so the reserved space
   becomes visible empty space. Override the reservation. */
.product__info-container--matching-set .matching-size-guide__snapshot,
.product__info-container--matching-set .matching-size-guide__snapshot--reserved,
.product__info-container--matching-set .matching-size-guide__snapshot--reserved:empty {
  display: none !important;
  min-height: 0 !important;
  visibility: hidden !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}
.product__info-container--matching-set variant-selects > details.matching-size-guide[hidden] {
  display: none !important;
}
.product__info-container--matching-set .product-form__quantity {
  display: none !important;
}

/* The legacy buy-buttons.liquid renders a 4-pill trust strip (Secure
   Checkout / 30-day return window / Free standard shipping / Family
   matching made easy) plus a "Need help?" line above the bundle card.
   That information is duplicated by the Purchase Confidence module
   below the CTA. Hide it on bundle products so the bundle leads. */
.product__info-container--matching-set .product__trust-strip,
.product__info-container--matching-set .product__trust-note {
  display: none !important;
}

/* Aggressively zero margins/padding on every Dawn block container that
   sits between the price block and the bundle on bundle products. This
   eliminates the residual whitespace the previous pass missed (the
   product-form, the volume-pricing note, low-stock-urgency div, the
   pickup availability shell, the size-conversion message, etc.). */
.product__info-container--matching-set .product-form {
  margin: 0 !important;
  padding: 0 !important;
}
.product__info-container--matching-set .product-form__error-message-wrapper,
.product__info-container--matching-set .product-form__error-message-wrapper:empty,
.product__info-container--matching-set .pickup-availability,
.product__info-container--matching-set .pickup-availability-preview,
.product__info-container--matching-set .pickup-availability-info,
.product__info-container--matching-set .volume-pricing-note,
.product__info-container--matching-set .low-stock-urgency:empty {
  display: none !important;
}
.product__info-container--matching-set product-form,
.product__info-container--matching-set product-form .product-form,
.product__info-container--matching-set .product-form__buttons {
  margin: 0 !important;
  padding: 0 !important;
  min-height: 0 !important;
}
/* If the buy_buttons block leaves an empty <product-form> shell behind
   (after we hide its visible children), collapse that shell entirely. */
.product__info-container--matching-set product-form:empty {
  display: none !important;
}
/* The variant_picker block emits a wrapper that might still claim
   vertical space even when its children are display:none — collapse
   the &lt;variant-selects&gt; element itself if all visible children are
   hidden. (The matching-size-guide details retains [hidden] from JS
   so it doesn't reserve space.) */
.product__info-container--matching-set variant-selects {
  display: block;
  margin: 0 !important;
  padding: 0 !important;
}

/* 2. Compress the picker → CTA distance.
   Dawn ships generous vertical rhythm; on bundle products we want the
   CTA inside the first mobile viewport. Trims ~40–60% off the gaps,
   and zeros-out the gap between the price block and the bundle card
   that opens up when we hide the variant picker + trust strip. */
.product__info-container--matching-set .product-form,
.product__info-container--matching-set .product-form__input {
  margin-top: 0.6rem;
  margin-bottom: 0.6rem;
}
.product__info-container--matching-set .matching-size-guide,
.product__info-container--matching-set .matching-size-guide__snapshot {
  margin-top: 0.6rem;
}
/* Collapse the variant_picker block when its children are all hidden
   on bundle products. The block container itself still paints unless
   we zero its margins. */
.product__info-container--matching-set .product-form {
  margin: 0;
}
.product__info-container--matching-set variant-selects:empty,
.product__info-container--matching-set variant-selects {
  margin: 0;
  padding: 0;
}
/* The buy-buttons block sits between price and bundle — its empty
   wrapper margins create the visible gap. */
.product__info-container--matching-set product-form {
  margin: 0;
}

/* 3. Purchase Confidence module — UPDATED May 11 2026.
   Initial pass hid .additional-info on bundle products in favor of a
   small 3-checkmark strip inside the bundle card. Frank flagged this
   removed useful info (shipping country, delivery date, returns,
   secure-checkout details, size-guide link). Restore the full module
   directly below the bundle CTA — DOM order in main-product.liquid
   already places .additional-info immediately after the bundle card,
   so a small spacing tweak gets it visually adjacent to the CTA. */
.product__info-container--matching-set ~ .additional-info,
[data-has-matching-set="true"] ~ .additional-info,
.product__info-wrapper:has(.product__info-container--matching-set) .additional-info {
  margin-top: 0.6rem;
}

/* On bundle products specifically, two parts of Purchase Confidence
   are redundant and we hide them:
   • .dlm-pc-compact-row (Secure checkout / Free shipping / 30-day
     returns / Ships to {country}) — duplicated by the three big
     promise rows directly below it inside the same card.
   • .dlm-pc-details (Size guide & fit → link) — now redundant
     because the per-pill pinned tooltip auto-shows measurements
     when a size is selected.
   Non-bundle products keep both elements untouched. */
.product__info-wrapper:has(.product__info-container--matching-set) .dlm-pc-compact-row,
.product__info-wrapper:has(.product__info-container--matching-set) .dlm-pc-details {
  display: none !important;
